package com.runebound.runelite;

import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

final class RuneBoundSummaryCache
{
	static final Duration SUCCESS_TTL = Duration.ofMinutes(15);
	static final Duration MIN_POLL_INTERVAL = Duration.ofMinutes(30);

	private final Map<String, RuneBoundCacheEntry> entries = new ConcurrentHashMap<>();
	private final Map<String, Instant> lastAttempts = new ConcurrentHashMap<>();

	void markAttempt(String username, Instant now)
	{
		lastAttempts.put(RuneBoundUsername.cacheKey(username), now);
	}

	Instant lastAttempt(String username)
	{
		final String normalized = RuneBoundUsername.normalize(username);
		return normalized == null ? null : lastAttempts.get(RuneBoundUsername.cacheKey(normalized));
	}

	Duration remainingBeforeNextAttempt(String username, Instant now)
	{
		final Instant lastAttempt = lastAttempt(username);
		if (lastAttempt == null)
		{
			return Duration.ZERO;
		}

		final Duration elapsed = Duration.between(lastAttempt, now);
		if (!elapsed.minus(MIN_POLL_INTERVAL).isNegative())
		{
			return Duration.ZERO;
		}

		return MIN_POLL_INTERVAL.minus(elapsed);
	}

	void put(String username, RuneBoundSummaryResult result, Instant now)
	{
		if (result == null)
		{
			throw new IllegalArgumentException("result is required");
		}

		entries.put(RuneBoundUsername.cacheKey(username), new RuneBoundCacheEntry(result, now, now.plus(SUCCESS_TTL)));
	}

	RuneBoundSummaryResult freshResult(String username, Instant now)
	{
		final String normalized = RuneBoundUsername.normalize(username);
		if (normalized == null)
		{
			return null;
		}

		final RuneBoundCacheEntry entry = entries.get(RuneBoundUsername.cacheKey(normalized));
		if (entry == null || entry.expiresAt.isBefore(now) || entry.expiresAt.equals(now))
		{
			return null;
		}

		return entry.result;
	}

	RuneBoundSummaryResult latestResult(String username)
	{
		final String normalized = RuneBoundUsername.normalize(username);
		if (normalized == null)
		{
			return null;
		}

		final RuneBoundCacheEntry entry = entries.get(RuneBoundUsername.cacheKey(normalized));
		return entry == null ? null : entry.result;
	}

	private static final class RuneBoundCacheEntry
	{
		private final RuneBoundSummaryResult result;
		private final Instant expiresAt;

		private RuneBoundCacheEntry(RuneBoundSummaryResult result, Instant fetchedAt, Instant expiresAt)
		{
			this.result = result;
			this.expiresAt = expiresAt;
		}
	}
}

package com.runebound.runelite;

import java.time.Duration;

final class RuneBoundBackoffPolicy
{
	private static final Duration INITIAL_FAILURE_BACKOFF = Duration.ofMinutes(5);
	private static final Duration MAX_FAILURE_BACKOFF = Duration.ofMinutes(60);

	private RuneBoundBackoffPolicy()
	{
	}

	static Duration delayForFailureCount(int failureCount)
	{
		if (failureCount <= 0)
		{
			return Duration.ZERO;
		}

		long minutes = INITIAL_FAILURE_BACKOFF.toMinutes();
		for (int index = 1; index < failureCount; index++)
		{
			minutes *= 2;
			if (minutes >= MAX_FAILURE_BACKOFF.toMinutes())
			{
				return MAX_FAILURE_BACKOFF;
			}
		}

		return Duration.ofMinutes(minutes);
	}
}

package com.runebound.runelite;

import java.net.URI;
import java.net.URISyntaxException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

final class RuneBoundUrls
{
	private static final String HOST = "rune-bound.net";
	private static final String PROFILE_BASE_URL = "https://rune-bound.net/player/";
	private static final String SUMMARY_BASE_URL = "https://rune-bound.net/api/runelite/v1/players/";

	private RuneBoundUrls()
	{
	}

	static String profileUrl(String username)
	{
		return PROFILE_BASE_URL + encodePathSegment(username);
	}

	static String summaryUrl(String username)
	{
		return SUMMARY_BASE_URL + encodePathSegment(username) + "/summary?client=runelite-v1";
	}

	static boolean isSafeProfileUrl(String url)
	{
		try
		{
			final URI uri = new URI(url == null ? "" : url);
			final String path = uri.getPath();
			return "https".equals(uri.getScheme()) &&
				HOST.equals(uri.getHost()) &&
				path != null &&
				path.startsWith("/player/") &&
				path.length() > "/player/".length() &&
				path.equals(uri.normalize().getPath()) &&
				uri.getQuery() == null &&
				uri.getFragment() == null;
		}
		catch (URISyntaxException exception)
		{
			return false;
		}
	}

	private static String encodePathSegment(String username)
	{
		final String normalizedUsername = RuneBoundUsername.normalize(username);
		if (normalizedUsername == null)
		{
			throw new IllegalArgumentException("username is required");
		}

		if (!RuneBoundUsername.isLookupCandidate(normalizedUsername))
		{
			throw new IllegalArgumentException("username is too long");
		}

		return URLEncoder.encode(normalizedUsername, StandardCharsets.UTF_8).replace("+", "%20");
	}
}

package com.runebound.runelite;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(RuneBoundConfig.CONFIG_GROUP)
public interface RuneBoundConfig extends Config
{
	String CONFIG_GROUP = "runebound";
	String THIRD_PARTY_WARNING = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers";

	@ConfigItem(
		keyName = "enableNetworkLookups",
		name = "Enable RuneBound summary lookups",
		description = "Default off. Allows explicit read-only summary lookups from rune-bound.net for a selected public display name. The plugin sends no gameplay data and does not trigger RuneBound refreshes.",
		position = 0,
		warning = THIRD_PARTY_WARNING
	)
	default boolean enableNetworkLookups()
	{
		return false;
	}
}
